#!/usr/bin/env node
/**
 * Every vendored request-interceptor worker is the same file, and the same file
 * the installed mock library would write.
 *
 * Why there are three of them: a service worker's scope is the origin that
 * served it. The shell and each remote's standalone page are three origins, so
 * the mocked lane needs three registrations and therefore three copies. That is
 * duplication the repo cannot design away.
 *
 * Why it needs a check: the copies are generated by `msw init`, and nothing
 * makes anyone run it in all three places. A partial regeneration — after a
 * dependency bump, or because one page misbehaved — leaves two origins on one
 * version and one on another, and the failure is silent in the direction that
 * matters most. The worker announces its own version to the page, so a mismatch
 * surfaces as a console warning nobody reads, and the lane keeps appearing to
 * work until the day a handler depends on newer behaviour.
 *
 * Checked against the installed library rather than only against each other, so
 * three identically stale copies still fail: agreement is not currency.
 *
 * Exits non-zero naming the copies that disagree.
 */
import { readFileSync, existsSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');

const COPIES = [
  'apps/shell/public/mockServiceWorker.js',
  'remotes/catalog/public/mockServiceWorker.js',
  'remotes/operations/public/mockServiceWorker.js',
];

const SOURCE = 'node_modules/msw/lib/mockServiceWorker.js';

const fail = (lines) => {
  console.error('check-worker-parity: FAIL\n');
  for (const line of lines) console.error(`  ${line}`);
  console.error(
    '\nRegenerate every copy from the installed library:\n' +
      COPIES.map((c) => `  npx msw init ${dirname(c)} --no-save`).join('\n'),
  );
  process.exit(1);
};

const source = join(ROOT, SOURCE);
if (!existsSync(source)) {
  // Not a failure: the library is a dev dependency and this can run in a
  // production install. Saying so is better than passing silently, which would
  // read as "the copies were checked".
  console.log('check-worker-parity: SKIP (the mock library is not installed)');
  process.exit(0);
}

const expected = readFileSync(source, 'utf8');
const version = expected.match(/PACKAGE_VERSION = '([^']+)'/)?.[1] ?? 'unknown';
const problems = [];

for (const copy of COPIES) {
  const path = join(ROOT, copy);
  if (!existsSync(path)) {
    problems.push(`${copy} is missing — that origin cannot intercept anything`);
    continue;
  }
  const actual = readFileSync(path, 'utf8');
  if (actual !== expected) {
    const found = actual.match(/PACKAGE_VERSION = '([^']+)'/)?.[1] ?? 'unknown';
    problems.push(
      found === version
        ? `${copy} differs from the installed ${version} worker (same version, edited content)`
        : `${copy} is version ${found}, installed is ${version}`,
    );
  }
}

if (problems.length > 0) fail(problems);

console.log(`check-worker-parity: PASS (${COPIES.length} copies match the installed ${version})`);
